import { useCallback, useEffect, useMemo, useState } from 'react'
import { Activity, AlertCircle, ArrowDownUp, ArrowRight, BookOpen, Bot, Check, CheckCircle2, ChevronDown, ChevronLeft, ChevronRight, CircleHelp, Clock3, Copy, FileText, FolderGit2, Gauge, GitBranch, LayoutDashboard, ListTodo, Menu, MoreHorizontal, Pencil, Plus, RefreshCw, Search, Settings, SlidersHorizontal, Sparkles, Sun, Upload, Workflow, X, Bell } from 'lucide-react'

type Task={id:string;title:string;description:string;due_at:string|null;priority:string;category:string;status:string;recurrence:string|null;reminder_at:string|null;reminder_enabled:boolean|number;completed_at:string|null}
type Session={id:string;subject_id:string|null;subject_name?:string;title:string;starts_at:string;duration_minutes:number;actual_minutes:number;status:string}
type Subject={id:string;name:string;color:string}
type Document={id:string;name:string;media_type:string;size_bytes:number;status:string;error:string|null;created_at:string;summary:string;summary_status:string;summary_error:string|null}
type Workflow={id:string;name:string;description:string;definition:{nodes:{id:string;name:string;type:string;config?:Record<string,unknown>}[];edges:{source:string;target:string}[]};enabled:boolean;schedule?:{enabled:number;next_run_at:string;recurrence:string|null;timezone:string;last_run_at:string|null;error:string|null}|null}
type Run={id:string;workflow_id:string|null;workflow_name:string;status:string;trigger_type:string;started_at:string;finished_at:string|null;error:string|null;logs:string}
type Agent={id:string;name:string;purpose:string;instructions:string;model:string}
type Data={tasks:Task[];subjects:Subject[];sessions:Session[];documents:Document[];workflows:Workflow[];runs:Run[];agents:Agent[];notifications:{id:string;title:string;body:string;created_at:string;read_at:string|null}[];settings:Record<string,string>}
type SearchHits={tasks:{id:string;title:string;status:string;due_at:string|null}[];documents:{id:string;name:string;status:string}[];workflows:{id:string;name:string}[]}
type Page='Overview'|'My Day'|'Tasks & Reminders'|'Study Planner'|'Documents'|'Workflows'|'AI Agents'|'Developer Hub'|'Execution History'|'Settings'
const nav:{label:Page;icon:typeof LayoutDashboard;group:string}[]=[{label:'Overview',icon:LayoutDashboard,group:'WORKSPACE'},{label:'My Day',icon:Sun,group:'WORKSPACE'},{label:'Tasks & Reminders',icon:ListTodo,group:'WORKSPACE'},{label:'Study Planner',icon:BookOpen,group:'WORKSPACE'},{label:'Documents',icon:FileText,group:'WORKSPACE'},{label:'Workflows',icon:Workflow,group:'AUTOMATION'},{label:'AI Agents',icon:Bot,group:'AUTOMATION'},{label:'Developer Hub',icon:FolderGit2,group:'AUTOMATION'},{label:'Execution History',icon:Activity,group:'AUTOMATION'},{label:'Settings',icon:Settings,group:'SYSTEM'}]
const blank:Data={tasks:[],subjects:[],sessions:[],documents:[],workflows:[],runs:[],agents:[],notifications:[],settings:{}}
let displayTimeZone:string|undefined
const api=async<T,>(path:string,init?:RequestInit):Promise<T>=>{const res=await fetch(path,{...init,headers:{...(init?.body instanceof FormData?{}:{'Content-Type':'application/json'}),...init?.headers}});if(!res.ok){let m=`Request failed (${res.status})`;try{m=(await res.json()).detail||m}catch{}throw Error(m)}return res.json()}
const dayKey=(v:string|null|undefined)=>v?new Date(v).toLocaleDateString('en-CA',{timeZone:displayTimeZone}):''
const time=(v:string|null|undefined)=>v?new Date(v).toLocaleTimeString([],{hour:'numeric',minute:'2-digit',timeZone:displayTimeZone}):''
const date=(v:string|null|undefined)=>v?new Date(v).toLocaleDateString([],{month:'short',day:'numeric',timeZone:displayTimeZone}):''
const toLocalInput=(v:string|null|undefined)=>{if(!v)return '';const d=new Date(v);d.setMinutes(d.getMinutes()-d.getTimezoneOffset());return d.toISOString().slice(0,16)}
const uid=()=>crypto.randomUUID()
const runStatus=(s:string)=><span className={`status-pill ${s}`}><i/>{s}</span>

export default function App(){
 const [page,setPage]=useState<Page>('Overview'),[data,setData]=useState<Data>(blank),[loading,setLoading]=useState(true),[error,setError]=useState(''),[collapsed,setCollapsed]=useState(localStorage.getItem('ff-sidebar')==='true'),[mobile,setMobile]=useState(false),[search,setSearch]=useState(''),[searchHits,setSearchHits]=useState<SearchHits>({tasks:[],documents:[],workflows:[]}),[create,setCreate]=useState(false),[editingTask,setEditingTask]=useState<Task|null>(null),[toast,setToast]=useState(''),[now,setNow]=useState(new Date())
 const refresh=useCallback(async()=>{try{const loaded=await api<Data>('/api/bootstrap');displayTimeZone=loaded.settings.timezone||undefined;setData(loaded);setError('')}catch(e){setError(e instanceof Error?e.message:'Could not load workspace')}finally{setLoading(false)}},[])
 useEffect(()=>{void refresh();const i=setInterval(()=>void refresh(),10000);return()=>clearInterval(i)},[refresh])
 useEffect(()=>{if(!search.trim()){setSearchHits({tasks:[],documents:[],workflows:[]});return}const timer=setTimeout(()=>{void api<SearchHits>(`/api/search?q=${encodeURIComponent(search)}`).then(setSearchHits).catch(()=>setSearchHits({tasks:[],documents:[],workflows:[]}))},180);return()=>clearTimeout(timer)},[search])
 useEffect(()=>{const i=setInterval(()=>setNow(new Date()),30000);return()=>clearInterval(i)},[])
 useEffect(()=>{if(!toast)return;const i=setTimeout(()=>setToast(''),3200);return()=>clearTimeout(i)},[toast])
 useEffect(()=>{const h=(e:KeyboardEvent)=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();document.getElementById('global-search')?.focus()}if(e.key==='Escape'){setCreate(false);setSearch('');setMobile(false)}};window.addEventListener('keydown',h);return()=>window.removeEventListener('keydown',h)},[])
 const notify=(s:string)=>setToast(s)
 const mutate=async<T,>(path:string,method:string,body?:unknown)=>{const r=await api<T>(path,{method,...(body===undefined?{}:{body:body instanceof FormData?body:JSON.stringify(body)})});await refresh();return r}
 const today=dayKey(now.toISOString()),open=data.tasks.filter(x=>x.status==='open'),dueToday=open.filter(x=>x.due_at&&dayKey(x.due_at)===today),overdue=open.filter(x=>x.due_at&&new Date(x.due_at)<new Date(today+'T00:00:00'))
 const header=useMemo(()=>({title:page,crumb:page==='Overview'?'YOUR WORKSPACE':page==='Developer Hub'?'AUTOMATION / REPOSITORIES':page==='Execution History'?'AUTOMATION / RUNS':nav.find(n=>n.label===page)?.group||'WORKSPACE'}),[page])
 const openCreate=()=>{setEditingTask(null);setCreate(true)}
 return <div className="app-shell">
  <aside className={`sidebar ${collapsed?'is-collapsed':''} ${mobile?'mobile-open':''}`}>
   <div className="brand"><div className="brand-mark"><Workflow size={17}/></div>{!collapsed&&<><span className="brand-name">flowforge</span><button className="icon-button sidebar-collapse" aria-label="Collapse sidebar" onClick={()=>{const v=!collapsed;setCollapsed(v);localStorage.setItem('ff-sidebar',String(v))}}><ChevronLeft size={16}/></button></>}</div>
   {collapsed&&<button className="icon-button expand-side" aria-label="Expand sidebar" onClick={()=>{setCollapsed(false);localStorage.setItem('ff-sidebar','false')}}><ChevronRight size={16}/></button>}
   {!collapsed&&<button className="workspace-switch"><span className="workspace-avatar">F</span><span className="workspace-copy"><b>Personal workspace</b><small>LOCAL · PRIVATE</small></span><ChevronDown size={14}/></button>}
   {['WORKSPACE','AUTOMATION','SYSTEM'].map(group=><div className="nav-group" key={group}><div className="nav-label">{!collapsed&&group}</div>{nav.filter(n=>n.group===group).map(item=><button key={item.label} title={collapsed?item.label:undefined} className={`nav-item ${page===item.label?'active':''}`} onClick={()=>{setPage(item.label);setMobile(false)}}><item.icon size={17}/>{!collapsed&&<span>{item.label}</span>}{item.label==='Tasks & Reminders'&&!collapsed&&dueToday.length>0&&<em>{dueToday.length}</em>}</button>)}</div>)}
   <div className="sidebar-bottom">{!collapsed&&<div className="local-badge"><span className="live-dot"/>Local workspace</div>}<button className="profile-button" onClick={()=>setPage('Settings')}><span className="profile-avatar">FF</span>{!collapsed&&<span className="profile-copy"><b>My account</b><small>Single-user mode</small></span>}{!collapsed&&<MoreHorizontal size={17} className="muted"/>}</button></div>
  </aside>
  {mobile&&<button aria-label="Close menu" className="mobile-scrim" onClick={()=>setMobile(false)}/>}
  <main className="main-area"><header className="topbar"><button className="icon-button mobile-menu" aria-label="Open menu" onClick={()=>setMobile(true)}><Menu size={19}/></button><div className="breadcrumbs"><span>{header.crumb}</span><b>/</b><strong>{page}</strong></div><div className="top-actions"><div className="search-wrap"><Search size={15}/><input id="global-search" placeholder="Search anything..." value={search} onChange={e=>setSearch(e.target.value)} /><kbd>⌘ K</kbd>{search&&<div className="search-popover">{searchHits.tasks.map(t=><button key={t.id} onClick={()=>{setPage('Tasks & Reminders');setSearch('')}}><ListTodo size={14}/>{t.title}<span>Task</span></button>)}{searchHits.documents.map(d=><button key={d.id} onClick={()=>{setPage('Documents');setSearch('')}}><FileText size={14}/>{d.name}<span>Document</span></button>)}{searchHits.workflows.map(w=><button key={w.id} onClick={()=>{setPage('Workflows');setSearch('')}}><Workflow size={14}/>{w.name}<span>Workflow</span></button>)}{!searchHits.tasks.length&&!searchHits.documents.length&&!searchHits.workflows.length&&<p>No matches found</p>}</div>}</div><button className="icon-button top-icon" title="Notifications" onClick={()=>setPage('Tasks & Reminders')}><Bell size={16}/>{data.notifications.filter(n=>!n.read_at).length>0&&<em>{data.notifications.filter(n=>!n.read_at).length}</em>}</button><button className="icon-button top-icon" title="Refresh workspace" onClick={()=>void refresh()}><RefreshCw size={16}/></button><button className="top-create" onClick={openCreate}><Plus size={16}/><span>Create</span></button></div></header>
   <div className="page-scroll"><div className="content-wrap"><div className="page-title-row"><div><div className="eyebrow">{now.toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric',year:'numeric',timeZone:displayTimeZone})}</div><h1>{page==='Overview'?`Good ${now.getHours()<12?'morning':now.getHours()<18?'afternoon':'evening'}.`:page}</h1><p className="page-subtitle">{page==='Overview'?'Here’s what’s happening across your workspace.':page==='My Day'?'A clear view of what needs your attention today.':page==='Developer Hub'?'Repository activity and delivery health.':page==='Workflows'?'Build and run reliable automations.':page==='Tasks & Reminders'?'Keep commitments visible and moving.':page==='Study Planner'?'Plan focused sessions and track progress.':page==='Documents'?'Your source files, ready to search and revisit.':page==='AI Agents'?'Purpose-built agents with explicit instructions.':page==='Execution History'?'Runs, statuses, and operational detail.':'Workspace preferences and integrations.'}</p></div><div className="page-title-actions">{page==='Overview'&&<button className="btn secondary" onClick={()=>setPage('My Day')}><Sun size={15}/> My day</button>}<button className="btn primary" onClick={openCreate}><Plus size={15}/>{page==='Tasks & Reminders'?'New task':page==='Workflows'?'New workflow':page==='Documents'?'Upload document':'Quick create'}</button></div></div>
   {error&&<div className="error-banner"><AlertCircle size={16}/><span>{error} · Is the local API running?</span><button onClick={()=>void refresh()}>Retry</button></div>}
   {loading?<div className="loading-state"><RefreshCw className="spin" size={18}/> Loading workspace…</div>:<PageView page={page} data={data} today={today} overdue={overdue} dueToday={dueToday} open={open} mutate={mutate} notify={notify} onCreate={openCreate} onEditTask={t=>{setEditingTask(t);setCreate(true)}} setPage={setPage} />}
   <footer className="page-footer"><span><span className="live-dot"/>LOCAL WORKSPACE</span><span>FlowForge <code>0.1.0</code></span></footer></div></div>
  </main>
  {create&&<CreateModal page={page} data={data} initialTask={editingTask||undefined} onClose={()=>{setCreate(false);setEditingTask(null)}} onCreate={async(kind,body)=>{const path=kind==='task'&&editingTask?`/api/tasks/${editingTask.id}`:kind==='task'?'/api/tasks':kind==='subject'?'/api/study/subjects':kind==='session'?'/api/study/sessions':kind==='workflow'?'/api/workflows':kind==='agent'?'/api/agents':'/api/documents';await mutate(path,kind==='task'&&editingTask?'PATCH':'POST',body);setCreate(false);setEditingTask(null);notify(kind==='task'&&editingTask?'Task updated':'Saved to your workspace')}}/>}
  {toast&&<div className="toast"><CheckCircle2 size={17}/>{toast}</div>}
 </div>
}

function PageView({page,data,today,overdue,dueToday,open,mutate,notify,onCreate,onEditTask,setPage}:{page:Page;data:Data;today:string;overdue:Task[];dueToday:Task[];open:Task[];mutate:<T,>(path:string,method:string,body?:unknown)=>Promise<T>;notify:(s:string)=>void;onCreate:()=>void;onEditTask:(task:Task)=>void;setPage:(p:Page)=>void}){
 const [tab,setTab]=useState('All'),[query,setQuery]=useState(''),[detail,setDetail]=useState<Run|null>(null),[github,setGithub]=useState<{configured:boolean;last_successful_refresh?:string;repositories?:{full_name:string;private:boolean;default_branch:string;updated_at:string;html_url:string}[];message?:string}|null>(null),[integrationConfig,setIntegrationConfig]=useState<{integrations:{ai_configured:boolean;github_configured:boolean;ai_model:string|null;github_owner:string|null};limits:{max_upload_mb:number;max_parallel_nodes:number}}|null>(null),[activity,setActivity]=useState<Record<string,unknown>|null>(null),[busy,setBusy]=useState('')
 const doneToday=data.tasks.filter(t=>t.status==='completed'&&dayKey(t.completed_at)===today).length; const sessionsToday=data.sessions.filter(s=>dayKey(s.starts_at)===today);const upcoming=data.sessions.filter(s=>s.status==='planned'&&new Date(s.starts_at)>=new Date()).slice(0,4)
 const complete=async(t:Task)=>{await mutate(`/api/tasks/${t.id}`,'PATCH',{status:t.status==='completed'?'open':'completed'});notify(t.status==='completed'?'Task reopened':'Task completed')}
 const recentRuns=data.runs.slice(0,5)
 useEffect(()=>{if(page==='Developer Hub')void api<typeof github>('/api/developer/status').then(setGithub).catch(e=>setGithub({configured:false,message:String(e)}))},[page])
 useEffect(()=>{if(page==='Settings')void api<typeof integrationConfig>('/api/settings').then(setIntegrationConfig).catch(()=>setIntegrationConfig(null))},[page])
 const run=async(id:string)=>{setBusy(id);try{await mutate(`/api/workflows/${id}/runs`,'POST');notify('Workflow started')}catch(e){notify(e instanceof Error?e.message:'Could not start workflow')}finally{setBusy('')}}
 const panel=(title:string,sub:string,action?:{label:string;go:()=>void},children?:React.ReactNode)=><section className="panel"><div className="panel-head"><div><h2>{title}</h2>{sub&&<p>{sub}</p>}</div>{action&&<button className="text-action" onClick={action.go}>{action.label}<ArrowRight size={14}/></button>}</div>{children}</section>
 const taskRows=(tasks:Task[],compact=false)=><div className={`task-list ${compact?'compact':''}`}>{tasks.length?tasks.map(t=><div className={`task-row ${t.status==='completed'?'is-done':''}`} key={t.id}><button className={`task-check ${t.status==='completed'?'checked':''}`} aria-label={t.status==='completed'?'Reopen task':'Complete task'} onClick={()=>void complete(t)}>{t.status==='completed'?<Check size={13}/>:null}</button><div className="task-main"><strong>{t.title}</strong>{!compact&&t.description&&<p>{t.description}</p>}</div><span className={`priority ${t.priority}`}>{t.priority}</span><span className="task-date">{t.due_at?date(t.due_at):'No due date'}</span>{!compact&&<button aria-label="Delete task" className="icon-button row-delete" onClick={()=>void mutate(`/api/tasks/${t.id}`,'DELETE').then(()=>notify('Task removed'))}><X size={14}/></button>}</div>):<div className="empty-inline"><CheckCircle2 size={16}/><span>Nothing here yet</span></div>}</div>
 if(page==='Overview')return <>
  <div className="overview-grid"><div className="overview-main">
   <section className="panel priorities-panel"><div className="panel-head"><div><div className="section-kicker"><Sun size={14}/> TODAY · {today}</div><h2>Daily priorities</h2><p>{dueToday.length} due today · {overdue.length} overdue · {open.length} open overall</p></div><button className="text-action" onClick={()=>setPage('My Day')}>Open my day <ArrowRight size={14}/></button></div>{taskRows([...overdue,...dueToday].slice(0,5),true)}<button className="add-row" onClick={onCreate}><Plus size={14}/> Add a task</button></section>
   <div className="split-panels">{panel('Upcoming study','Planned sessions', {label:'Study planner',go:()=>setPage('Study Planner')},<div className="session-list">{upcoming.length?upcoming.map(s=><div className="session-row" key={s.id}><div className="session-time">{time(s.starts_at)}</div><div className="session-marker"/><div className="session-info"><strong>{s.title}</strong><small>{s.subject_name||'Independent study'} · {s.duration_minutes} min</small></div></div>):<div className="empty-inline">No sessions scheduled</div>}</div>)}{panel('Workflow activity','Latest executions',{label:'View history',go:()=>setPage('Execution History')},<div className="run-list">{recentRuns.length?recentRuns.slice(0,4).map(r=><button className="run-row" key={r.id} onClick={()=>setDetail(r)}><span className={`run-symbol ${r.status}`}><Workflow size={14}/></span><span className="run-info"><strong>{r.workflow_name}</strong><small>{date(r.started_at)} · {time(r.started_at)}</small></span>{runStatus(r.status)}</button>):<div className="empty-inline">No executions recorded</div>}</div>)}</div>
   {panel('Recently updated documents','Most recent additions',{label:'All documents',go:()=>setPage('Documents')},<div className="document-list">{data.documents.slice(0,3).map(d=><div className="document-row" key={d.id}><span className="file-icon"><FileText size={16}/></span><span className="document-info"><strong>{d.name}</strong><small>{(d.size_bytes/1024).toFixed(0)} KB · {date(d.created_at)}</small></span><span className={`mini-status ${d.status}`}>{d.status}</span></div>)}{!data.documents.length&&<div className="empty-inline">No documents added yet</div>}</div>)}
  </div><aside className="overview-side"><div className="date-card"><span className="date-weekday">{new Date().toLocaleDateString(undefined,{weekday:'long',timeZone:displayTimeZone})}</span><strong>{new Date().toLocaleDateString(undefined,{day:'numeric',timeZone:displayTimeZone})}</strong><span>{new Date().toLocaleDateString(undefined,{month:'long',year:'numeric',timeZone:displayTimeZone})}</span><div className="date-rule"/><div className="date-progress"><span>Today’s completion</span><b>{dueToday.length?Math.round(doneToday/(doneToday+dueToday.length)*100):doneToday?100:0}%</b></div><div className="progress-track"><i style={{width:`${dueToday.length?Math.round(doneToday/(doneToday+dueToday.length)*100):doneToday?100:0}%`}}/></div></div>
  <section className="panel compact-panel"><div className="panel-head"><div><h2>At a glance</h2><p>Live from your workspace</p></div><Gauge size={16} className="muted"/></div><div className="glance-row"><span>Open tasks</span><b>{open.length}</b></div><div className="glance-row"><span>Completed today</span><b>{doneToday}</b></div><div className="glance-row"><span>Study sessions today</span><b>{sessionsToday.length}</b></div><div className="glance-row"><span>Active workflows</span><b>{data.runs.filter(r=>r.status==='running').length}</b></div><div className="glance-row"><span>Documents stored</span><b>{data.documents.length}</b></div></section>
  <section className="panel nudge-panel"><div className="nudge-icon"><Sparkles size={16}/></div><div><strong>Make space to focus</strong><p>{overdue.length?`${overdue.length} overdue task${overdue.length===1?'':'s'} need a quick review.`:'Add your next priority to keep today on track.'}</p><button className="text-action" onClick={()=>setPage(overdue.length?'Tasks & Reminders':'Study Planner')}>{overdue.length?'Review overdue':'Plan a session'} <ArrowRight size={13}/></button></div></section>
  </aside></div><RunDetail run={detail} close={()=>setDetail(null)} />
 </>
 if(page==='My Day')return <div className="myday-layout"><div className="myday-main">{panel('Today’s focus',`${dueToday.length} items due · ${overdue.length} overdue`,undefined,<>{taskRows([...overdue,...dueToday])}<button className="add-row" onClick={onCreate}><Plus size={14}/> Add a priority</button></>)}{panel('Completed',`${doneToday} completed tasks in your workspace`,undefined,taskRows(data.tasks.filter(t=>t.status==='completed'&&dayKey(t.completed_at)===today),true))}</div><aside className="myday-aside"><section className="panel"><div className="panel-head"><div><h2>Time blocks</h2><p>Your planned work today</p></div><button className="icon-button" onClick={()=>setPage('Study Planner')}><ArrowRight size={15}/></button></div>{sessionsToday.length?sessionsToday.map(s=><div className="time-block" key={s.id}><span>{time(s.starts_at)}</span><div><b>{s.title}</b><small>{s.duration_minutes} min · {s.subject_name||'Study'}</small></div></div>):<div className="empty-box"><Clock3 size={20}/><b>No time blocks yet</b><span>Schedule a study session to reserve focus time.</span><button className="btn secondary" onClick={()=>setPage('Study Planner')}>Plan a session</button></div>}</section><section className="panel"><div className="panel-head"><div><h2>Daily summary</h2><p>Based on saved activity</p></div></div><p className="summary-copy">You have <b>{open.length} open task{open.length===1?'':'s'}</b> and <b>{sessionsToday.length} study session{sessionsToday.length===1?'':'s'}</b> scheduled today. {overdue.length?`${overdue.length} overdue item${overdue.length===1?'':'s'} could use attention.`:'No overdue tasks.'}</p></section></aside></div>
 if(page==='Tasks & Reminders'){const filtered=data.tasks.filter(t=>(tab==='All'||(tab==='Open'?t.status==='open':tab==='Completed'?t.status==='completed':t.priority==='urgent'||t.priority==='high'))&&(!query||`${t.title} ${t.description}`.toLowerCase().includes(query.toLowerCase())));return <>{<div className="list-toolbar"><div className="tabs">{['All','Open','Completed','High priority'].map(t=><button className={tab===t?'selected':''} onClick={()=>setTab(t)} key={t}>{t}{t==='All'&&<span>{data.tasks.length}</span>}</button>)}</div><div className="toolbar-right"><div className="inline-search"><Search size={14}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Filter tasks"/></div><button className="btn primary" onClick={onCreate}><Plus size={15}/> New task</button></div></div>}<section className="panel task-table-panel"><div className="table-header"><span>Task</span><span>Priority</span><span>Category</span><span>Due date</span><span>Status</span><span/></div>{filtered.map(t=><div className="table-row" key={t.id}><button className={`task-check ${t.status==='completed'?'checked':''}`} onClick={()=>void complete(t)} aria-label="Toggle completion">{t.status==='completed'?<Check size={13}/>:null}</button><div className="table-task"><b className={t.status==='completed'?'strike':''}>{t.title}</b><small>{t.description||'No description'}{t.reminder_at?` · Reminder ${t.reminder_enabled?'on':'paused'} ${date(t.reminder_at)} ${time(t.reminder_at)}`:''}</small></div><span className={`priority ${t.priority}`}>{t.priority}</span><span className="table-category">{t.category}</span><span className="task-date">{t.due_at?date(t.due_at):'—'} {t.due_at&&time(t.due_at)}</span><span className={`status-pill ${t.status}`}><i/>{t.status}</span><button className="icon-button row-delete" onClick={()=>onEditTask(t)} aria-label="Edit task"><Pencil size={14}/></button><button className="icon-button row-delete" onClick={()=>void mutate(`/api/tasks/${t.id}`,'DELETE').then(()=>notify('Task removed'))} aria-label="Delete task"><X size={14}/></button></div>)}{!filtered.length&&<div className="empty-box"><ListTodo size={24}/><b>{query?'No matching tasks':'Your task list is clear'}</b><span>{query?'Try another search.':'Create a task to keep your next action visible.'}</span>{!query&&<button className="btn secondary" onClick={onCreate}><Plus size={14}/> Create a task</button>}</div>}</section><section className="panel" style={{marginTop:14}}><div className="panel-head"><div><h2>Reminder history</h2><p>In-app alerts saved on this device</p></div></div>{data.notifications.length?data.notifications.map(n=><div key={n.id} className="notification-row"><span><b>{n.title}</b><small>{n.body} · {date(n.created_at)} {time(n.created_at)}</small></span>{!n.read_at&&<button className="text-action" onClick={()=>void mutate(`/api/notifications/${n.id}/read`,'POST').then(()=>notify('Marked as read'))}>Mark read</button>}</div>):<div className="empty-inline">No reminders delivered yet</div>}</section><div className="list-footnote"><CircleHelp size={14}/> Reminders run locally while FlowForge is open. Missed one-time reminders are delivered after restart.</div></>}
 if(page==='Study Planner')return <div className="study-layout"><div className="study-main"><section className="panel"><div className="panel-head"><div><h2>Study sessions</h2><p>Plan focused blocks and record what you completed</p></div><button className="btn primary" onClick={onCreate}><Plus size={14}/> Schedule session</button></div><div className="study-calendar-head"><span>UPCOMING</span><button className="text-action" onClick={onCreate}>Add session <ArrowRight size={14}/></button></div>{data.sessions.length?data.sessions.slice().sort((a,b)=>a.starts_at.localeCompare(b.starts_at)).map(s=><div className="study-card" key={s.id}><div className="study-datebox"><b>{new Date(s.starts_at).getDate()}</b><span>{new Date(s.starts_at).toLocaleDateString(undefined,{month:'short'}).toUpperCase()}</span></div><div className="study-card-main"><b>{s.title}</b><span>{s.subject_name||'Independent study'} · {time(s.starts_at)} · {s.duration_minutes} min</span><div className="session-progress"><i style={{width:s.status==='completed'?'100%':'0%'}}/></div></div><span className={`status-pill ${s.status}`}><i/>{s.status}</span>{s.status==='planned'&&<button className="btn small secondary" onClick={()=>void mutate(`/api/study/sessions/${s.id}`,'PATCH',{status:'completed',actual_minutes:s.duration_minutes}).then(()=>notify('Session completed'))}>Mark done</button>}</div>):<div className="empty-box"><BookOpen size={25}/><b>No study sessions planned</b><span>Add a subject and schedule your first focus block.</span><button className="btn secondary" onClick={onCreate}><Plus size={14}/> Plan study</button></div>}</section><section className="panel"><div className="panel-head"><div><h2>Subjects</h2><p>Your study areas</p></div><button className="text-action" onClick={onCreate}><Plus size={14}/> Add subject</button></div><div className="subject-list">{data.subjects.map(s=><div className="subject-row" key={s.id}><span style={{background:s.color}}/><b>{s.name}</b><small>{data.sessions.filter(x=>x.subject_id===s.id).length} sessions</small></div>)}{!data.subjects.length&&<div className="empty-inline">Subjects you add will appear here</div>}</div></section></div><aside className="study-side"><section className="panel"><div className="panel-head"><div><h2>This week</h2><p>Planned study time</p></div></div><div className="week-total"><b>{data.sessions.reduce((n,s)=>n+s.duration_minutes,0)}</b><span>minutes scheduled</span></div><div className="week-bars">{['M','T','W','T','F','S','S'].map((d,i)=>{const base=new Date();const monday=new Date(base);monday.setDate(base.getDate()-((base.getDay()+6)%7)+i);const mins=data.sessions.filter(s=>dayKey(s.starts_at)===dayKey(monday.toISOString())).reduce((a,s)=>a+s.duration_minutes,0);return <div key={i}><span>{d}</span><i><b style={{height:`${Math.min(100,mins/3)}%`}}/></i></div>})}</div></section><section className="panel revision-note"><BookOpen size={17}/><b>Keep it realistic</b><p>Plan sessions you can complete. Mark finished blocks to build an accurate record of your study time.</p></section></aside></div>
 if(page==='Documents')return <><div className="list-toolbar"><div className="tabs"><button className="selected">All documents <span>{data.documents.length}</span></button></div><div className="toolbar-right"><button className="btn primary" onClick={onCreate}><Upload size={15}/> Upload files</button></div></div><section className="panel docs-panel"><div className="table-header docs-header"><span>Name</span><span>Type</span><span>Size</span><span>Added</span><span>Status</span><span/></div>{data.documents.map(d=><div className="docs-row" key={d.id}><span className="file-icon"><FileText size={16}/></span><div className="table-task"><b>{d.name}</b><small>{d.error||d.summary_error||d.summary||'Original preserved · text extracted locally'}</small></div><span className="muted">{d.media_type==='application/pdf'?'PDF':d.media_type.split('/').pop()?.toUpperCase()}</span><span className="muted">{(d.size_bytes/1024).toFixed(1)} KB</span><span className="muted">{date(d.created_at)}</span><span className={`mini-status ${d.status}`}>{d.status}</span><div className="doc-actions">{d.summary_status==='completed'?<button className="icon-button" title="View AI summary" onClick={()=>window.alert(d.summary)}><Sparkles size={14}/></button>:<button className="icon-button" title="Send extracted text to configured AI provider for summary" disabled={d.summary_status==='processing'||d.status!=='processed'} onClick={()=>{if(window.confirm('This sends the extracted document text to the configured external AI provider. Continue?'))void mutate(`/api/documents/${d.id}/summarize`,'POST').then(()=>notify('Summary created')).catch(e=>notify(String(e)))}}><Sparkles size={14}/></button>}{d.status==='failed'&&<button className="icon-button" title="Retry text extraction" onClick={()=>void mutate(`/api/documents/${d.id}/retry`,'POST').then(()=>notify('Document reprocessed'))}><RefreshCw size={14}/></button>}<button className="icon-button" title="Download original" onClick={()=>window.open(`/api/documents/${d.id}/download`,'_blank')}><ArrowDownUp size={14}/></button><button className="icon-button" title="Delete" onClick={()=>void mutate(`/api/documents/${d.id}`,'DELETE').then(()=>notify('Document deleted'))}><X size={14}/></button></div></div>)}{!data.documents.length&&<div className="empty-box"><FileText size={24}/><b>No documents yet</b><span>Upload a PDF, text, Markdown, or CSV file to store and search its contents.</span><button className="btn secondary" onClick={onCreate}><Upload size={14}/> Upload document</button></div>}</section><div className="list-footnote"><CircleHelp size={14}/> Summaries send extracted text to your configured external AI provider only after confirmation. Original files remain unchanged.</div></>
 if(page==='Workflows')return <><div className="list-toolbar"><div className="tabs"><button className="selected">Workflows <span>{data.workflows.length}</span></button></div><div className="toolbar-right"><button className="btn primary" onClick={onCreate}><Plus size={15}/> New workflow</button></div></div><div className="workflow-layout"><section className="panel workflow-panel"><div className="panel-head"><div><h2>Saved workflows</h2><p>Validated dependency graphs, persisted locally</p></div><Workflow size={17} className="muted"/></div>{data.workflows.map(w=><div className="workflow-card" key={w.id}><div className="workflow-top"><div className="workflow-symbol"><Workflow size={17}/></div><div className="workflow-card-title"><b>{w.name}</b><small>{w.description||'No description'}</small></div><span className={`mini-status ${w.enabled?'completed':'cancelled'}`}>{w.enabled?'enabled':'disabled'}</span></div><div className="node-flow">{w.definition.nodes.map((n,i)=><span key={n.id}><i className={`node-dot ${n.type}`}/>{n.name}{i<w.definition.nodes.length-1&&<ArrowRight size={13}/>}</span>)}</div>{w.schedule&&<div className="schedule-row"><span><b>{w.schedule.recurrence||'One time'}</b><small>Next {date(w.schedule.next_run_at)} · {time(w.schedule.next_run_at)} · {w.schedule.timezone}</small></span><button className="btn small secondary" onClick={()=>void mutate(`/api/workflows/${w.id}/schedule?enabled=${!w.schedule?.enabled}`,'PATCH').then(()=>notify('Schedule updated'))}>{w.schedule.enabled?'Pause':'Resume'} schedule</button></div>}<div className="workflow-bottom"><span>{w.definition.nodes.length} nodes · {w.definition.edges.length} dependencies</span><button className="btn small primary" disabled={!!busy} onClick={()=>void run(w.id)}>{busy===w.id?<RefreshCw className="spin" size={13}/>:<Activity size={13}/>} Run workflow</button><button className="icon-button" title="Duplicate workflow" onClick={()=>void mutate(`/api/workflows/${w.id}/duplicate`,'POST').then(()=>notify('Workflow duplicated'))}><Copy size={14}/></button><button className="icon-button" title="Delete workflow" onClick={()=>void mutate(`/api/workflows/${w.id}`,'DELETE').then(()=>notify('Workflow deleted'))}><X size={14}/></button></div></div>)}{!data.workflows.length&&<div className="empty-box"><Workflow size={24}/><b>No workflows defined</b><span>Start with a simple transform, or build a multi-step sequence.</span><button className="btn secondary" onClick={onCreate}><Plus size={14}/> Create workflow</button></div>}</section><aside className="panel workflow-aside"><div className="panel-head"><div><h2>Run activity</h2><p>Most recent executions</p></div><button className="text-action" onClick={()=>setPage('Execution History')}>All runs <ArrowRight size={13}/></button></div>{recentRuns.slice(0,5).map(r=><button className="history-mini" key={r.id} onClick={()=>setDetail(r)}><span className={`run-symbol ${r.status}`}><Workflow size={13}/></span><span><b>{r.workflow_name}</b><small>{date(r.started_at)} · {time(r.started_at)}</small></span>{runStatus(r.status)}</button>)}{!recentRuns.length&&<div className="empty-inline">No runs to show</div>}</aside></div><RunDetail run={detail} close={()=>setDetail(null)} /></>
 if(page==='Execution History')return <><div className="list-toolbar"><div className="tabs"><button className="selected">All executions <span>{data.runs.length}</span></button></div><div className="toolbar-right"><button className="icon-button" title="Refresh" onClick={()=>location.reload()}><RefreshCw size={15}/></button></div></div><section className="panel execution-table"><div className="table-header exec-header"><span>Workflow</span><span>Trigger</span><span>Started</span><span>Duration</span><span>Status</span><span/></div>{data.runs.map(r=><div className="exec-row" key={r.id}><span className="exec-name"><span className={`run-symbol ${r.status}`}><Workflow size={14}/></span><b>{r.workflow_name}</b></span><span className="muted">{r.trigger_type}</span><span className="muted">{date(r.started_at)} {time(r.started_at)}</span><span className="muted">{r.finished_at?Math.max(0,Math.round((new Date(r.finished_at).getTime()-new Date(r.started_at).getTime())/1000))+'s':'—'}</span>{runStatus(r.status)}<button className="text-action" onClick={()=>setDetail(r)}>Details <ArrowRight size={13}/></button></div>)}{!data.runs.length&&<div className="empty-box"><Activity size={24}/><b>No executions recorded</b><span>Run a saved workflow to see its execution here.</span><button className="btn secondary" onClick={()=>setPage('Workflows')}>Browse workflows</button></div>}</section><RunDetail run={detail} close={()=>setDetail(null)} /></>
 if(page==='AI Agents')return <><div className="list-toolbar"><div className="tabs"><button className="selected">Agent registry <span>{data.agents.length}</span></button></div><div className="toolbar-right"><button className="btn primary" onClick={onCreate}><Plus size={15}/> New agent</button></div></div><div className="agent-grid">{data.agents.map(a=><section className="panel agent-card" key={a.id}><div className="agent-card-head"><div className="agent-avatar"><Bot size={18}/></div><button className="icon-button" onClick={()=>void mutate(`/api/agents/${a.id}`,'DELETE').then(()=>notify('Agent removed'))}><X size={14}/></button></div><b>{a.name}</b><p>{a.purpose||'No purpose described.'}</p><div className="agent-model"><span>MODEL</span><b>{a.model||'Workflow default'}</b></div><div className="agent-card-foot"><span className="mini-status configured">READY TO ASSIGN</span><span>{a.instructions?'Instructions set':'No instructions'}</span></div></section>)}{!data.agents.length&&<div className="empty-box agent-empty"><Bot size={25}/><b>No agents configured</b><span>Agents are reusable instruction sets. Assign them to an AI node in a workflow.</span><button className="btn secondary" onClick={onCreate}><Plus size={14}/> Create agent</button></div>}</div><section className="info-strip"><AlertCircle size={15}/><span>AI execution requires an OpenAI-compatible provider configured in <code>.env</code>. Agent definitions are stored locally; approval gates for external actions are not yet available.</span><button className="text-action" onClick={()=>setPage('Settings')}>Integration settings <ArrowRight size={13}/></button></section></>
 if(page==='Developer Hub')return <><div className="developer-banner"><div className="dev-banner-icon"><GitBranch size={20}/></div><div><b>GitHub repository connection</b><p>Read-only repository activity using a personal access token from the local environment.</p></div><span className={`connection-state ${integrationConfig?.integrations.github_configured?'connected':''}`}><i/>{github?.configured ? 'CONNECTED' : 'NOT CONFIGURED'}</span></div>{github?.configured?<><div className="list-footnote">Last successful refresh: {github.last_successful_refresh?`${date(github.last_successful_refresh)} ${time(github.last_successful_refresh)}`:'not available'} · Live data is read-only.</div><div className="repo-grid">{github.repositories?.map(repo=><section className="panel repo-card" key={repo.full_name}><div className="repo-top"><span className="repo-icon"><FolderGit2 size={16}/></span><span className="mini-status configured">{repo.private?'PRIVATE':'PUBLIC'}</span></div><a href={repo.html_url} target="_blank" rel="noreferrer">{repo.full_name}</a><div className="repo-meta"><span><GitBranch size={13}/>{repo.default_branch}</span><span>Updated {date(repo.updated_at)}</span></div><button className="btn secondary full-width" onClick={()=>void api<Record<string,unknown>>(`/api/developer/repositories/${repo.full_name}/activity`).then(setActivity).catch(e=>notify(String(e)))}>View recent activity</button></section>)}</div></>:<section className="panel github-empty"><div className="github-mark"><GitBranch size={23}/></div><h2>Connect your repositories</h2><p>{github?.message||'Repository data will appear here when GitHub credentials are configured.'}</p><div className="setup-code"><code>FLOWFORGE_GITHUB_TOKEN=ghp_…<br/>FLOWFORGE_GITHUB_OWNER=your-user</code></div><button className="text-action" onClick={()=>setPage('Settings')}>View setup instructions <ArrowRight size={14}/></button></section>}{activity&&<section className="panel activity-panel"><div className="panel-head"><div><h2>Repository activity</h2><p>Pull requests, commits, and GitHub Actions</p></div><button className="icon-button" onClick={()=>setActivity(null)}><X size={15}/></button></div><pre>{JSON.stringify(activity,null,2)}</pre></section>}<div className="list-footnote"><CircleHelp size={14}/> Credentials remain in the local backend environment. This integration reads repository activity only; it does not execute code or create pull requests.</div></>
 if(page==='Settings')return <div className="settings-layout"><div className="settings-main"><section className="panel settings-panel"><div className="settings-section-title"><div><h2>General</h2><p>Workspace and regional preferences</p></div></div><label className="setting-row"><span><b>Time zone</b><small>Used for dates, reminders, and study sessions</small></span><select value={data.settings.timezone||'Asia/Calcutta'} onChange={e=>void mutate('/api/settings/timezone','PUT',{value:e.target.value}).then(()=>notify('Time zone saved'))}><option>Asia/Calcutta</option><option>UTC</option><option>America/Los_Angeles</option><option>America/New_York</option><option>Europe/London</option><option>Europe/Berlin</option><option>Asia/Tokyo</option><option>Australia/Sydney</option></select></label><div className="setting-row"><span><b>Workspace mode</b><small>Data stays on this machine</small></span><span className="mini-status configured">SINGLE USER · LOCAL</span></div></section><section className="panel settings-panel"><div className="settings-section-title"><div><h2>Integrations</h2><p>Optional services configured in your <code>.env</code> file</p></div><SlidersHorizontal size={16} className="muted"/></div><div className="integration-row"><div className="integration-icon ai"><Sparkles size={16}/></div><div className="integration-copy"><b>AI provider</b><small>OpenAI-compatible chat completions API</small></div><span className={`connection-state ${integrationConfig?.integrations.ai_configured?'connected':''}`}><i/>{integrationConfig?.integrations.ai_configured ? 'CONNECTED' : 'NOT CONFIGURED'}</span></div><div className="integration-row"><div className="integration-icon gh"><GitBranch size={16}/></div><div className="integration-copy"><b>GitHub</b><small>Read-only repository, PR, commits, and Actions status</small></div><span className={`connection-state ${integrationConfig?.integrations.github_configured?'connected':''}`}><i/>{integrationConfig?.integrations.github_configured?'CONNECTED':'OPTIONAL'}</span></div><div className="settings-note"><CircleHelp size={14}/><span>Credentials are read by the local backend only and never sent to the browser. See <code>.env.example</code> for available settings.</span></div></section><section className="panel settings-panel"><div className="settings-section-title"><div><h2>Execution limits</h2><p>Guardrails for local processing</p></div></div><div className="setting-row"><span><b>Concurrent workflow nodes</b><small>Maximum parallel tasks per run</small></span><code>{data.workflows.length?'Configured by FLOWFORGE_MAX_PARALLEL_NODES':'{integrationConfig?.limits.max_parallel_nodes??4}'}</code></div><div className="setting-row"><span><b>Upload limit</b><small>PDF, TXT, Markdown, and CSV</small></span><code>{integrationConfig?.limits.max_upload_mb??20} MB</code></div></section></div><aside className="settings-aside"><div className="security-card"><div className="security-icon"><CheckCircle2 size={18}/></div><b>Private by default</b><p>The API binds to <code>127.0.0.1</code>. No login is provided; do not expose this service on a network.</p><div className="security-rule"/><span><i/>LOCALHOST BINDING</span><span><i/>SECRETS SERVER-SIDE</span><span><i/>ORIGINAL FILES RETAINED</span></div><section className="panel about-panel"><span className="brand-mark"><Workflow size={15}/></span><b>FlowForge</b><small>Personal workflow workspace</small><code>Version 0.1.0 · local development</code></section></aside></div>
 return null
}

function RunDetail({run,close}:{run:Run|null;close:()=>void}){const [full,setFull]=useState<Record<string,unknown>|null>(null),[busy,setBusy]=useState(false),[actionError,setActionError]=useState('');useEffect(()=>{if(run)void api<Record<string,unknown>>(`/api/runs/${run.id}`).then(setFull).catch(()=>setFull(null));else setFull(null)},[run?.id]);if(!run)return null;const status=String(full?.status||run.status);const nodes=(full?.nodes||[]) as {node_id:string;node_name:string;status:string;started_at:string|null;finished_at:string|null;output:string|null;error:string|null;attempts:number}[];const action=async(kind:'approve'|'cancel'|'retry')=>{setBusy(true);setActionError('');try{await api(`/api/runs/${run.id}/${kind}`,{method:'POST'});await new Promise(r=>setTimeout(r,150));setFull(await api<Record<string,unknown>>(`/api/runs/${run.id}`))}catch(e){setActionError(e instanceof Error?e.message:'Run action failed')}finally{setBusy(false)}};return <div className="modal-backdrop" onClick={close}><section className="modal run-modal" onClick={e=>e.stopPropagation()}><div className="modal-head"><div><div className="eyebrow">EXECUTION DETAIL</div><h2>{run.workflow_name}</h2></div><button className="icon-button" onClick={close}><X size={17}/></button></div><div className="run-detail-meta">{runStatus(status)}<span>{date(run.started_at)} · {time(run.started_at)}</span></div>{(run.error||actionError)&&<div className="error-banner"><AlertCircle size={15}/>{actionError||run.error}</div>}<div className="run-node-list">{nodes.map(n=><div className="run-node" key={n.node_id}><span className={`node-state ${n.status}`}>{n.status==='completed'?<Check size={13}/>:n.status==='running'?<RefreshCw size={13}/>:<X size={13}/>}</span><div><b>{n.node_name}</b><small>{n.status} · {n.attempts} attempt{n.attempts===1?'':'s'}</small>{n.error&&<pre>{n.error}</pre>}{n.output&&<details><summary>Output</summary><pre>{n.output}</pre></details>}</div></div>)}{!nodes.length&&<div className="empty-inline">Loading node details…</div>}</div><div className="modal-foot"><span>Run ID <code>{run.id.slice(0,8)}</code></span><div>{status==='paused'&&<button className="btn primary" disabled={busy} onClick={()=>void action('approve')}>{busy?<RefreshCw size={13} className="spin"/>:<Check size={13}/>} Approve and continue</button>}{['running','paused'].includes(status)&&<button className="btn secondary" disabled={busy} onClick={()=>void action('cancel')}>Cancel run</button>}{['failed','cancelled'].includes(status)&&<button className="btn primary" disabled={busy} onClick={()=>void action('retry')}>{busy?<RefreshCw size={13} className="spin"/>:<RefreshCw size={13}/>} Retry run</button>}<button className="btn secondary" onClick={close}>Close</button></div></div></section></div>}

function CreateModal({page,data,initialTask,onClose,onCreate}:{page:Page;data:Data;initialTask?:Task;onClose:()=>void;onCreate:(kind:string,body:unknown)=>Promise<void>}){const [kind,setKind]=useState(initialTask?'task':page==='Study Planner'?'session':page==='Workflows'?'workflow':page==='AI Agents'?'agent':page==='Documents'?'document':'task'),[busy,setBusy]=useState(false),[error,setError]=useState('');const [title,setTitle]=useState(initialTask?.title||''),[desc,setDesc]=useState(initialTask?.description||''),[due,setDue]=useState(toLocalInput(initialTask?.due_at)),[priority,setPriority]=useState(initialTask?.priority||'medium'),[category,setCategory]=useState(initialTask?.category||'personal'),[recurrence,setRecurrence]=useState(initialTask?.recurrence||''),[reminder,setReminder]=useState(toLocalInput(initialTask?.reminder_at)),[reminderEnabled,setReminderEnabled]=useState(initialTask?!!initialTask.reminder_enabled:true),[scheduleAt,setScheduleAt]=useState(''),[scheduleRecurrence,setScheduleRecurrence]=useState(''),[scheduleTimezone,setScheduleTimezone]=useState('Asia/Calcutta'),[subject,setSubject]=useState(''),[start,setStart]=useState(''),[duration,setDuration]=useState('45'),[color,setColor]=useState('#52796f'),[nodes,setNodes]=useState<{id:string;name:string;type:string;config:{output:unknown;agent_id?:string;prompt?:string}}[]>([{id:uid().slice(0,8),name:'Prepare',type:'transform',config:{output:{message:'Ready'}}},{id:uid().slice(0,8),name:'Review',type:'transform',config:{output:{approved:true}}}]),[agentPurpose,setAgentPurpose]=useState(''),[instructions,setInstructions]=useState(''),[model,setModel]=useState(''),[inputSchema,setInputSchema]=useState('{}'),[outputSchema,setOutputSchema]=useState('{}')
 useEffect(()=>{if(initialTask){setKind('task');setTitle(initialTask.title);setDesc(initialTask.description);setDue(toLocalInput(initialTask.due_at));setPriority(initialTask.priority);setCategory(initialTask.category);setRecurrence(initialTask.recurrence||'');setReminder(toLocalInput(initialTask.reminder_at));setReminderEnabled(!!initialTask.reminder_enabled)}},[initialTask])
 const submit=async(e:React.FormEvent)=>{e.preventDefault();setError('');setBusy(true);try{let body:unknown;if(kind==='task')body={title,description:desc,due_at:due?new Date(due).toISOString():null,priority,category,recurrence:recurrence||null,reminder_at:reminder?new Date(reminder).toISOString():null,reminder_enabled:reminderEnabled};if(kind==='subject')body={name:title,color};if(kind==='session')body={title,subject_id:subject||null,starts_at:start?new Date(start).toISOString():new Date(Date.now()+3600000).toISOString(),duration_minutes:Number(duration),notes:desc};if(kind==='workflow')body={name:title,description:desc,nodes,edges:nodes.slice(1).map((n,i)=>({source:nodes[i].id,target:n.id})),schedule_at:scheduleAt?new Date(scheduleAt).toISOString():null,schedule_recurrence:scheduleAt?(scheduleRecurrence||null):null,schedule_timezone:scheduleTimezone};if(kind==='agent')body={name:title,purpose:agentPurpose,instructions,model,input_schema:JSON.parse(inputSchema),output_schema:JSON.parse(outputSchema)};if(kind==='document'){const input=document.getElementById('document-input') as HTMLInputElement;const form=new FormData();if(input.files?.[0])form.append('file',input.files[0]);else throw Error('Choose a file to upload');body=form}await onCreate(kind,body)}catch(e){setError(e instanceof Error?e.message:'Could not save');setBusy(false)}}
 const heading:Record<string,string>={task:'Create task',session:'Schedule study session',subject:'Add subject',workflow:'Create workflow',agent:'Configure agent',document:'Upload document'}
 return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><section className="modal create-modal"><div className="modal-head"><div><div className="eyebrow">WORKSPACE ACTION</div><h2>{initialTask?'Edit task':heading[kind]}</h2></div><button className="icon-button" onClick={onClose} aria-label="Close"><X size={17}/></button></div>{!['task','session','workflow','agent','document','subject'].includes(page==='Workflows'?'workflow':page==='Study Planner'?'session':page==='AI Agents'?'agent':page==='Documents'?'document':'task')&&null}<div className="modal-tabs">{[['task','Task'],['session','Study'],['workflow','Workflow'],['agent','Agent'],['document','File'],['subject','Subject']].map(([k,l])=><button className={kind===k?'selected':''} key={k} onClick={()=>setKind(k)}>{l}</button>)}</div><form onSubmit={submit}><label className="field-label">{kind==='subject'?'Subject name':kind==='agent'?'Agent name':kind==='workflow'?'Workflow name':'Title'}<input required value={title} onChange={e=>setTitle(e.target.value)} placeholder={kind==='task'?'e.g. Submit project outline':kind==='session'?'e.g. Review chapter 4':kind==='workflow'?'e.g. Daily review':kind==='agent'?'e.g. Study planner':'e.g. Biology'}/></label>{kind==='task'&&<><label className="field-label">Description <textarea value={desc} onChange={e=>setDesc(e.target.value)} rows={3} placeholder="Add useful context"/></label><div className="field-grid"><label className="field-label">Due date<input type="datetime-local" value={due} onChange={e=>setDue(e.target.value)}/></label><label className="field-label">Priority<select value={priority} onChange={e=>setPriority(e.target.value)}><option value="low">Low</option><option value="medium">Medium</option><option value="high">High</option><option value="urgent">Urgent</option></select></label></div><label className="field-label">Category<input value={category} onChange={e=>setCategory(e.target.value)} placeholder="personal, study, work…"/></label><div className="field-grid"><label className="field-label">Reminder at<input type="datetime-local" value={reminder} onChange={e=>setReminder(e.target.value)}/></label><label className="field-label">Repeat reminder<select value={recurrence} onChange={e=>setRecurrence(e.target.value)}><option value="">One time</option><option value="daily">Daily</option><option value="weekdays">Weekdays</option><option value="weekly">Weekly</option></select></label></div><label className="check-row"><input type="checkbox" checked={reminderEnabled} onChange={e=>setReminderEnabled(e.target.checked)}/> Reminder enabled</label></>}{kind==='session'&&<><label className="field-label">Subject<select value={subject} onChange={e=>setSubject(e.target.value)}><option value="">Independent study</option>{data.subjects.map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</select></label><div className="field-grid"><label className="field-label">Start time<input type="datetime-local" value={start} onChange={e=>setStart(e.target.value)}/></label><label className="field-label">Duration (minutes)<input type="number" min="1" max="1440" value={duration} onChange={e=>setDuration(e.target.value)}/></label></div><label className="field-label">Notes<textarea value={desc} onChange={e=>setDesc(e.target.value)} rows={2}/></label></>}{kind==='subject'&&<label className="field-label">Color<input type="color" value={color} onChange={e=>setColor(e.target.value)}/></label>}{kind==='workflow'&&<><label className="field-label">Description<textarea rows={2} value={desc} onChange={e=>setDesc(e.target.value)} placeholder="What should this workflow do?"/></label><div className="workflow-editor-head"><span>SEQUENCE · DEPENDENCIES RUN IN ORDER</span><button type="button" className="text-action" onClick={()=>setNodes([...nodes,{id:uid().slice(0,8),name:`Step ${nodes.length+1}`,type:'transform',config:{output:{completed:true}}}])}><Plus size={13}/> Add node</button></div><div className="workflow-editor">{nodes.map((n,i)=><div className="workflow-edit-node" key={n.id}><span className="node-number">{i+1}</span><input aria-label="Node name" value={n.name} onChange={e=>setNodes(nodes.map(x=>x.id===n.id?{...x,name:e.target.value}:x))}/><select aria-label="Node type" value={n.type} onChange={e=>setNodes(nodes.map(x=>x.id===n.id?{...x,type:e.target.value}:x))}><option value="transform">Transform</option><option value="agent">AI agent</option><option value="manual">Manual approval</option><option value="http">HTTP (disabled)</option></select>{n.type==='agent'&&<select aria-label="Assigned agent" value={n.config.agent_id||''} onChange={e=>setNodes(nodes.map(x=>x.id===n.id?{...x,config:{...x.config,agent_id:e.target.value}}:x))}><option value="">Choose agent</option>{data.agents.map(a=><option key={a.id} value={a.id}>{a.name}</option>)}</select>}{nodes.length>1&&<button type="button" className="icon-button" onClick={()=>setNodes(nodes.filter(x=>x.id!==n.id))}><X size={14}/></button>}</div>)}</div><div className="field-grid"><label className="field-label">First run<input type="datetime-local" value={scheduleAt} onChange={e=>setScheduleAt(e.target.value)}/></label><label className="field-label">Repeat<select value={scheduleRecurrence} onChange={e=>setScheduleRecurrence(e.target.value)}><option value="">One time</option><option value="daily">Daily</option><option value="weekdays">Weekdays</option><option value="weekly">Weekly</option></select></label></div><label className="field-label">Schedule timezone<input value={scheduleTimezone} onChange={e=>setScheduleTimezone(e.target.value)} placeholder="IANA timezone"/></label><label className="field-label">Final output <textarea rows={2} value={JSON.stringify(nodes[nodes.length-1]?.config?.output||{},null,2)} onChange={e=>{try{const output=JSON.parse(e.target.value);setNodes(nodes.map((n,i)=>i===nodes.length-1?{...n,config:{output}}:n))}catch{}}}/></label></>}{kind==='agent'&&<><label className="field-label">Purpose<textarea rows={2} value={agentPurpose} onChange={e=>setAgentPurpose(e.target.value)}/></label><label className="field-label">Instructions<textarea required rows={4} value={instructions} onChange={e=>setInstructions(e.target.value)} placeholder="Describe the agent’s task and constraints"/></label><label className="field-label">Model (optional)<input value={model} onChange={e=>setModel(e.target.value)} placeholder="Uses configured workflow model"/></label><div className="field-grid"><label className="field-label">Input JSON schema<textarea rows={3} value={inputSchema} onChange={e=>setInputSchema(e.target.value)} spellCheck={false}/></label><label className="field-label">Output JSON schema<textarea rows={3} value={outputSchema} onChange={e=>setOutputSchema(e.target.value)} spellCheck={false}/></label></div></>}{kind==='document'&&<><label className="field-label file-input-label"><Upload size={20}/><b>Choose a document</b><span>PDF, TXT, Markdown, CSV · up to configured limit</span><input id="document-input" type="file" accept=".pdf,.txt,.md,.markdown,.csv,application/pdf,text/plain,text/markdown,text/csv" required/></label></>}{error&&<div className="form-error"><AlertCircle size={15}/>{error}</div>}<div className="modal-foot"><span className="muted">Saved to local workspace</span><div><button type="button" className="btn secondary" onClick={onClose}>Cancel</button><button className="btn primary" disabled={busy}>{busy&&<RefreshCw size={13} className="spin"/>}{kind==='document'?'Upload':kind==='workflow'?'Save workflow':'Save'}</button></div></div></form></section></div>}
